-- D-29 Pest Prevention Program: FSQM-031 and FRM-914 Pest Activity Log, both DRAFT.
--
-- Six Non-Compliant findings, 11.2.4.1 to 11.2.4.6. FSQM-031 is reserved in the remediation workbook; the
-- workbook leaves the log as FRM-9xx, and FRM-914 is the next free number in the 900s (sanitation and GMP)
-- block after FRM-913.
--
-- Owner's answers, 2026-09-29: the contractor (Control Pest Management) comes monthly and emails a report
-- of what it did; at least three bait stations outside; a sighting or droppings is reported to the
-- contractor and nothing is written down; no pesticides on site, the contractor brings and removes them;
-- trending is done monthly on the GMP inspection, by the SQF Practitioner or a delegate.
--
-- What already exists is reused, not duplicated: the daily device check (FRM-903), the monthly GMP
-- inspection row 11.2.4 (FRM-913 - its Finding column takes the monthly count and trend, so FRM-913 is
-- not changed), the contractor's entry on FRM-206, and "no pesticides on site" from FSQM-032.
-- FRM-914 is one entry per event - a staff sighting or a contractor visit, with the emailed report
-- attached. Staff create their own entries, which is what the response RLS allows.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-031', 'FRM-914')) then
    raise exception 'FSQM-031 or FRM-914 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FRM-206', 'FRM-903', 'FRM-905', 'FRM-913', 'FRM-301', 'FRM-702', 'FRM-007', 'FSQM-009', 'FSQM-012', 'FSQM-018', 'FSQM-032', 'FSQM-037') and status = 'active') <> 12 then
    raise exception 'a document D-29 names is missing or not active.';
  end if;
  if not exists (select 1 from public.sop_documents where sop_number = 'FSQM-028') then
    raise exception 'FSQM-028 (the site risk assessment FSQM-031 cites) does not exist.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-031', 'Pest Prevention Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '11.2.4.1, 11.2.4.2, 11.2.4.3, 11.2.4.4, 11.2.4.5, 11.2.4.6', true, $q${"purpose": "This program states how Adventure Bakery keeps pests out of the building, finds them early if they get in, and deals with them, so that pests never contaminate product, ingredients or packaging.", "scope": "The whole building and the area immediately outside it - the yard, the doors and the dumpster area - including the bait stations placed there. Pesticides are applied only by the contracted pest control service; none are kept on site.", "definitions": "Pest: rodents, insects, birds or any other animal that can contaminate food.\nSigns of pests: droppings, gnaw marks, nests, webs, live or dead insects, or damaged packaging.\nBait station: a locked box, placed by the contractor, holding poison bait for rodents.\nService report: the contractor's written account of each visit - what was inspected, what was found and what was applied.", "responsibility": "SQF Practitioner - owns this program; is the contractor's contact; reviews every service report and every FRM-914 entry; trends pest activity at the monthly GMP inspection, which may be delegated.\nProduction staff - check each day that pest devices are in place and intact; report any pest or sign of pests at once and record it on FRM-914; never open, move or touch a bait station.\nPest control contractor - licensed; services the site monthly; brings and removes every pesticide it uses; sends a written report after each visit.", "procedure": ["The contractor", "• Pest control is done by a licensed contractor listed on the Contract Services Register, FRM-206, with the technician's state pesticide applicator licence and the contract (SQF 11.2.4.2 i, ii).", "• The contractor visits monthly, services every device, inspects the building inside and out for pest activity, and treats where it is needed (SQF 11.2.4.1 v, 11.2.4.2 vi).", "• On arrival the technician signs in on FRM-905 and tells the SQF Practitioner, or whoever is in charge, that they are on site; before leaving they say what they found (SQF 11.2.4.2 v).", "• The contractor emails a written service report after each visit. It is attached to an FRM-914 entry for that visit, so every inspection and treatment is on record (SQF 11.2.4.2 vii, 11.2.4.3).", "• The contractor supplies the site's pest prevention plan, including a numbered map of every bait station, trap and monitoring device. The map is attached to this program and replaced whenever a device is added, moved or removed (SQF 11.2.4.1 vi, 11.2.4.2 iv).", "Keeping pests out", "• Outside doors are kept closed, and gaps, damaged seals and holes in the building are checked monthly on the GMP inspection, FRM-913 (SQF 11.2.4.1 iii).", "• Waste is bagged, taken out at the end of the day and kept in the lidded dumpster, lid closed, under FSQM-037.", "• Spills and food debris are cleaned up when they happen, and the building is cleaned under the SSOPs and FRM-903, so nothing is left for pests to feed on.", "• Deliveries are checked for signs of pests at receipt on FRM-301, and anything showing them is refused or held.", "• No animals are allowed on site in any food handling or storage area (SQF 11.2.4.6).", "• The risk from pests is assessed in the Site and Local Environment Risk Assessment, FSQM-028, which names pest pressure from the shared complex and its waste area as the site's main outside risk (SQF 11.2.4.3).", "Checking for pests", "• Every day: production staff check that pest devices are in place and intact on FRM-903.", "• Every month: the contractor's service visit, and the GMP inspection on FRM-913, row 11.2.4 - no signs of pests, devices in place and matching the map, service reports current (SQF 11.2.4.1 v, 11.2.4.3).", "When pests or signs of pests are found", "• Anyone who sees a pest or signs of pests tells the SQF Practitioner at once and records it on FRM-914 the same day: where, what was seen, and whether any product, ingredient or packaging was exposed (SQF 11.2.4.1 ii).", "• The SQF Practitioner reports it to the contractor, who inspects and treats. Pests are eliminated by the contractor only - staff never apply pesticides or set bait (SQF 11.2.4.1 iv).", "• Product, ingredients or packaging that may have been reached by pests are held under FSQM-018 on FRM-702. Anything contaminated is disposed of, and the disposal is recorded there (SQF 11.2.4.4).", "• Where activity is found inside the building, or product was affected, the source is investigated and resolved as a CAPA on FRM-007 under FSQM-009, and the CAPA number is recorded on the FRM-914 entry (SQF 11.2.4.4).", "Pesticides", "• No pesticides are kept on site. The contractor brings every pesticide it uses and takes it away again, so 11.6.4 storage does not arise (SQF 11.2.4.5; FSQM-032).", "• The contractor uses only pesticides registered for use by the relevant authority, and supplies a list of the products it applies here with their Safety Data Sheets. The list and the SDS are attached to this program and kept current (SQF 11.2.4.1 vii, 11.2.4.2 iii).", "• Only the contractor's licensed technicians handle pest control chemicals and baits, so the training 11.2.4.1 ix asks for is the technician's licence, held on FRM-206. Staff are trained to recognise signs of pests and to leave baits alone (SQF 11.2.4.1 ix).", "Bait stations - what staff must know", "• Staff are shown where the bait stations are, using the device map, when they start and in their GMP training (FSQM-012) (SQF 11.2.4.1 viii).", "• Staff never open, move, kick or lean anything against a bait station.", "• A bait station found open, damaged, moved or with bait spilled is not touched. Staff tell the SQF Practitioner, it is recorded on FRM-914, and the contractor is called. Anyone who does touch bait washes their hands at once and tells the SQF Practitioner (SQF 11.2.4.1 viii).", "Trending and effectiveness", "• At the monthly GMP inspection, the SQF Practitioner, or whoever they delegate, reviews that month's FRM-914 entries and the contractor's service report, counts the sightings and the activity the contractor found by area and by pest, compares them with the previous months, and records the count and whether it is rising, steady or falling in the Finding column of FRM-913 row 11.2.4 (SQF 11.2.4.1 ii, x).", "• Rising activity, or activity found twice in the same place, is raised as a CAPA on FRM-007 and taken to the contractor, so treatment is aimed where the activity is (SQF 11.2.4.1 ii).", "• The program is working when there is no pest activity inside the building and no product has been affected. It is reviewed at least once a year and whenever the contractor, the devices or the building change (SQF 11.2.4.1 x)."], "form_references": "FRM-914 - Pest Activity Log\nFRM-913 - GMP / Food Safety Inspection Record (row 11.2.4, monthly check and trend)\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record (devices in place and intact)\nFRM-905 - Visitor Sign-In Log\nFRM-206 - Contract Services Register (the contractor, licence and contract)\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective & Preventive Action Report", "records": "• FRM-914 entries, each contractor visit with its emailed service report attached\n• FRM-913 monthly GMP inspections, row 11.2.4, with the monthly count and trend\n• FRM-903 daily device checks\n• FRM-206 contractor entry with applicator licence and contract\n• The device map and the contractor's pesticide list and SDS, attached to this program\n• FRM-702 and FRM-007 where raised", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.2.4.1 to 11.2.4.6 (Pest Prevention).\n\nFSQM-028 Site and Local Environment Risk Assessment - the pest risk this program controls.\nFSQM-012 Good Manufacturing Practices Program and FRM-913 - the monthly inspection.\nFSQM-037 Waste Management Program - waste and the dumpster.\nFSQM-032 Chemical Control Program - no pesticides kept on site.\nFSQM-018 Non-Conforming Product - held and contaminated product.\nFSQM-009 CAPA Program - investigating the source.", "revision_history": "New - 2026-09-29 - DRAFT under D-29, for the six Non-Compliant findings against 11.2.4.1 to 11.2.4.6.\n\nWHAT THE SITE DOES NOW (owner, 2026-09-29): pest control is contracted to Control Pest Management, who visit once a month and email a report of the services they performed. There are at least three bait stations outside the building. A pest sighting or droppings is reported to the contractor; nothing has been written down on site. No pesticides are kept on site - the contractor brings them and takes them away. The SQF Practitioner, or someone she delegates, does the monthly GMP inspection, and trending is done there.\n\nNEW WITH THIS PROGRAM: sightings are recorded on FRM-914 rather than only reported, each contractor visit's emailed report is attached to an FRM-914 entry, and the monthly count and trend are written on FRM-913 row 11.2.4. No new inspection is added - the trend rides on the inspection the site already does.\n\nTHE CONTRACTOR IS NOT NAMED IN THE PROCEDURE, so changing contractor does not reissue this program; the current one is recorded on FRM-206.\n\nTO CONFIRM BEFORE ISSUE: (1) the contractor's numbered device map, to attach; (2) the list of pesticides the contractor applies here, with their SDS, to attach; (3) that the technician signs in and reports to someone on arrival - 11.2.4.2 v asks for it; (4) the technician's applicator licence on the FRM-206 entry, still open under D-10."}$q$::jsonb),
  ('FRM-914', 'Pest Activity Log', 'form', 'Module 11', 'draft', 'New',
   '11.2.4.1, 11.2.4.3, 11.2.4.4', true, jsonb_build_object('form_schema', $b${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{event_date} - {event_type}"}, "sections": [{"id": "event", "title": "1. What happened", "fields": [{"id": "how_this_works", "type": "info", "label": "One entry per event", "text": "Record every pest or sign of pests anyone finds, the same day, and every visit by the pest control contractor. For a contractor visit, attach the service report they email."}, {"id": "event_date", "type": "date", "label": "Date", "width": "third", "required": true, "defaultToday": true, "showInList": true}, {"id": "event_type", "type": "select", "label": "Type", "width": "third", "required": true, "showInList": true, "options": ["Sighting or signs found by staff", "Contractor monthly service", "Contractor call-out", "Bait station open, damaged or moved"]}, {"id": "location", "type": "text", "label": "Where", "width": "third", "required": true, "showInList": true, "help": "Room and spot, or the device number from the map. For a monthly service, 'Whole site'."}, {"id": "pest", "type": "select", "label": "Pest", "multiple": true, "required": true, "options": ["None found", "Rodent", "Cockroach", "Flying insect", "Stored-product insect", "Ant", "Bird", "Other"]}, {"id": "what_seen", "type": "textarea", "label": "What was seen or found", "required": true, "help": "Live or dead pests, droppings, gnaw marks, nests, damaged packaging. For a service visit, what the contractor reported."}]}, {"id": "product", "title": "2. Product", "fields": [{"id": "exposed", "type": "select", "label": "Was any product, ingredient or packaging exposed?", "required": true, "options": ["No", "Yes - held under FSQM-018 on FRM-702"]}, {"id": "hold_ref", "type": "text", "label": "FRM-702 hold tag, and what happened to it", "help": "Disposed of, or released after checking"}, {"id": "capa", "type": "select", "label": "Source investigated", "required": true, "help": "A CAPA is needed for activity inside the building, product affected, or activity twice in the same place", "options": ["Not needed - outside the building, no product affected", "CAPA raised on FRM-007"]}, {"id": "capa_number", "type": "text", "label": "CAPA number", "width": "half"}]}, {"id": "contractor", "title": "3. Contractor", "fields": [{"id": "contractor_told", "type": "select", "label": "Contractor", "width": "half", "required": true, "options": ["Told - date below", "This entry is the contractor's visit"]}, {"id": "contractor_told_on", "type": "date", "label": "Contractor told on", "width": "half"}, {"id": "treatment", "type": "textarea", "label": "What the contractor did", "help": "Devices serviced, treatment applied and product used, as on their report"}, {"id": "report", "type": "select", "label": "Service report", "width": "half", "options": ["Attached to this entry", "Not received yet", "Not applicable - no visit"]}]}, {"id": "sign", "title": "4. Sign-off", "fields": [{"id": "recorded_by", "type": "signature", "label": "Recorded by", "role": "filler", "required": true, "statement": "I have recorded what was found accurately."}, {"id": "reviewed_by", "type": "signature", "label": "Reviewed by the SQF Practitioner", "role": "verifier", "required": true, "statement": "I have reviewed this entry, the action taken and any effect on product."}]}]}$b$::jsonb));

do $verify$
declare p jsonb; fs jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-031';
  if jsonb_array_length(p) <> 33 then
    raise exception 'FSQM-031 procedure is % lines, expected 33.', jsonb_array_length(p);
  end if;
  -- every limb of 11.2.4.1 from ii to x is cited in the procedure (limb i is the Responsibility section)
  if (select count(*) from unnest(array['11.2.4.1 ii', '11.2.4.1 iii', '11.2.4.1 iv', '11.2.4.1 v', '11.2.4.1 vi',
                                        '11.2.4.1 vii', '11.2.4.1 viii', '11.2.4.1 ix', '11.2.4.1 x']) lim
       where p::text like '%' || lim || '%') <> 9 then
    raise exception 'FSQM-031 does not cite every limb of 11.2.4.1.';
  end if;
  select content->'form_schema' into fs from public.sop_documents where sop_number = 'FRM-914';
  if (select count(*) from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f
       where f->>'type' = 'signature' and f->>'role' = 'verifier') <> 1 then
    raise exception 'FRM-914 must carry exactly one verifier signature.';
  end if;
end $verify$;

commit;
